// --- Accessor function implementations -----------------------
const char* msg_get_name(MessageId id) {
    return _msg_names[_msg_string_id[uint16_t(id)]];
}

const char* msg_get_desc(MessageId id) {
    return _msg_descs[_msg_string_id[uint16_t(id)]];
}

MessageSeverity msg_get_severity(MessageId id) {
    return MessageSeverity(message_values[uint16_t(id)] >> 28);
}

const char* severity_label(MessageSeverity s) {
    return _severity_labels[uint8_t(s)];
}

int8_t msg_get_group_idx(MessageId id) {
    return msg_group_idx[uint16_t(id)];
}

const char* group_name(int8_t group_idx) {
    return msg_group_nodes[group_idx].name;
}

int8_t group_parent(int8_t group_idx) {
    return msg_group_nodes[group_idx].parent;
}
